    .hero-bg .poster:nth-child(15) { background: linear-gradient(135deg, #2a2a4a, #1a1a3a); }
    .hero-bg .poster:nth-child(16) { background: linear-gradient(135deg, #4a2a2a, #3a1a1a); }
