    .carousel-btn:hover { background: rgba(40,40,40,0.9); border-color: var(--grey-mid); }
    .carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }

    .carousel-wrapper {
      position: relative;
      overflow: hidden;
      padding: 0 48px;
    }

    .carousel-track {
      display: flex;
      gap: 16px;
      transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      will-change: transform;
