    .trending-card {
      flex: 0 0 auto;
      width: 220px;
      position: relative;
      cursor: pointer;
    }

    .trending-card .poster-img {
      width: 100%;
      height: 310px;
      border-radius: 8px;
      object-fit: cover;
      display: block;
    }

    .trending-card .poster-placeholder {
      width: 100%;
      height: 310px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 1.125rem;
      text-align: center;
      padding: 16px;
      position: relative;
      overflow: hidden;
    }

    .trending-card .rank {
      position: absolute;
      bottom: -10px;
      left: -10px;
      font-size: 8rem;
      font-weight: 900;
      line-height: 1;
      color: rgba(255,255,255,0.08);
      -webkit-text-stroke: 2px rgba(255,255,255,0.15);
      pointer-events: none;
      user-select: none;
    }

    .trending-card .title-label {
      margin-top: 12px;
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--grey-light);
    }

    /* ─── FEATURES ─── */
    .features {
      padding: 56px 48px;
      background: var(--bg);
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
      max-width: 1100px;
      margin: 0 auto;
    }

    .feature-card {
      background: linear-gradient(145deg, #1a1a2e, #16213e);
      border-radius: 16px;
      padding: 28px 24px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 280px;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .feature-card:nth-child(1) { background: linear-gradient(145deg, #1a1a2e, #16213e); }
    .feature-card:nth-child(2) { background: linear-gradient(145deg, #2e1a1a, #3e1621); }
    .feature-card:nth-child(3) { background: linear-gradient(145deg, #1a2e1a, #163e21); }
    .feature-card:nth-child(4) { background: linear-gradient(145deg, #2e2e1a, #3e3516); }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.5);
    }

    .feature-title {
      font-size: 1.375rem;
      font-weight: 800;
      margin-bottom: 12px;
      line-height: 1.2;
    }

    .feature-desc {
      font-size: 0.9375rem;
      color: var(--grey-mid);
      line-height: 1.5;
    }

    .feature-icon {
      align-self: flex-end;
      margin-top: 20px;
      width: 48px;
      height: 48px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.75rem;
    }

    /* ─── FAQ ─── */
    .faq {
      padding: 56px 48px;
      background: var(--bg);
    }

    .faq-list {
      max-width: 800px;
      margin: 32px auto 0;
    }

    .faq-item {
      margin-bottom: 8px;
    }

    .faq-question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 20px 24px;
      background: #2a2a2a;
      border: none;
      border-radius: 4px;
      color: var(--white);
      font-family: var(--font);
      font-size: 1.0625rem;
      font-weight: 500;
      text-align: left;
      cursor: pointer;
      transition: background 0.2s;
    }

    .faq-question:hover { background: #353535; }

    .faq-question .icon {
      font-size: 1.5rem;
      transition: transform 0.3s;
      flex-shrink: 0;
      margin-left: 16px;
    }

    .faq-item.open .faq-question .icon {
      transform: rotate(45deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s ease, padding 0.4s ease;
    }

    .faq-answer-inner {
      padding: 20px 24px;
      background: #2a2a2a;
      border-top: 2px solid #141414;
      font-size: 1rem;
      color: var(--grey-light);
      line-height: 1.6;
    }

    .faq-item.open .faq-answer {
      max-height: 400px;
    }

    /* ─── CTA ─── */
    .cta {
      padding: 56px 48px;
      background: var(--bg);
      text-align: center;
    }

    .cta-prompt {
      font-size: clamp(1.125rem, 2vw, 1.25rem);
      color: var(--grey-mid);
      margin-bottom: 20px;
    }

    /* ─── FOOTER ─── */
    .footer {
      padding: 48px;
      background: var(--bg);
      border-top: 1px solid #232323;
    }

    .footer-contact {
      font-size: 0.9375rem;
      color: var(--grey-dark);
      margin-bottom: 24px;
    }

    .footer-contact a {
      color: var(--grey-mid);
      text-decoration: underline;
    }

    .footer-links {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-bottom: 24px;
    }

    .footer-links a {
      font-size: 0.8125rem;
      color: var(--grey-dark);
      text-decoration: none;
      transition: color 0.2s;
    }

    .footer-links a:hover { color: var(--grey-light); text-decoration: underline; }

    .footer-bottom {
      margin-top: 16px;
    }

    .footer-bottom .lang-select {
      margin-bottom: 16px;
    }

    .footer-legal {
      font-size: 0.75rem;
      color: var(--grey-dark);
      line-height: 1.5;
    }

    .footer-legal a { color: var(--grey-mid); text-decoration: underline; }

    /* ─── RESPONSIVE ─── */
    @media (max-width: 1024px) {
      .features-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .header { padding: 16px 20px; }
      .trending-header { padding: 0 20px; }
      .carousel-wrapper { padding: 0 20px; }
      .features { padding: 40px 20px; }
      .faq { padding: 40px 20px; }
      .cta { padding: 40px 20px; }
      .footer { padding: 32px 20px; }

      .hero-title { font-size: 1.75rem; }
      .hero-subtitle { font-size: 1.0625rem; }

      .email-form {
        flex-direction: column;
        gap: 12px;
      }

      .btn-get-started {
        justify-content: center;
        padding: 14px 24px;
      }

      .features-grid { grid-template-columns: 1fr; gap: 12px; }

      .feature-card { min-height: auto; padding: 24px 20px; }

      .footer-links { grid-template-columns: repeat(2, 1fr); }

      .trending-card { width: 160px; }
      .trending-card .poster-placeholder { height: 230px; }
    }

    @media (max-width: 480px) {
      .hero { min-height: 80vh; }
      .hero-content { padding: 0 16px; }
      .logo { font-size: 1.375rem; }
      .lang-select { display: none; }
      .footer-links { grid-template-columns: repeat(2, 1fr); }
    }
  </style>
